    pattern = "".join(pattern_chars)

    for name in filenames:
        if len(name) != length:
            print("No")
            return

        match = True
        for i in range(length):
            p_char = pattern[i]
            f_char = name[i]
            if p_char == '?':
                continue
            if p_char != f_char:
                match = False
                break
        if match:
            if name not in target_filenames:
                print("No")
                return

    print("Yes")
    print(pattern)

